const journal=document.querySelector('[data-journal]');
if(journal){const input=journal.querySelector('[data-journal-search]'),cards=[...journal.querySelectorAll('[data-journal-card]')],buttons=[...journal.querySelectorAll('[data-journal-category]')];let category=new URLSearchParams(location.search).get('category')||'';if(!buttons.some(b=>b.dataset.journalCategory===category))category='';const render=()=>{const query=input.value.trim().toLocaleLowerCase();let count=0;for(const card of cards){card.hidden=!!((category&&card.dataset.category!==category)||(query&&!card.dataset.search.includes(query)));if(!card.hidden)count++;}journal.querySelectorAll('[data-journal-group]').forEach(group=>group.hidden=![...group.querySelectorAll('[data-journal-card]')].some(card=>!card.hidden));buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.journalCategory===category)));journal.querySelector('[data-journal-count]').textContent=count+' guide'+(count===1?'':'s')+' · review drafts';journal.querySelector('[data-journal-empty]').hidden=count>0||category==='Neighbor Stories';journal.querySelector('[data-neighbor-prompt]').hidden=category!=='Neighbor Stories';};buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.journalCategory;render();}));input.addEventListener('input',render);journal.querySelector('[data-journal-reset]').addEventListener('click',()=>{category='';input.value='';render();input.focus();});render();}
const tabs=[...document.querySelectorAll('[data-storage-panel]')];
function activateTab(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById('storage-panel-'+t.dataset.storagePanel).hidden=!active;});}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activateTab(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();activateTab(tabs[next]);tabs[next].focus();}});});
const storyGallery=document.querySelector('[data-story-gallery]');if(storyGallery){const filters=[...storyGallery.querySelectorAll('[data-story-filter]')],cards=[...storyGallery.querySelectorAll('[data-story-card]')];const render=()=>{cards.forEach(c=>c.hidden=filters.some(f=>f.value&&c.dataset[f.dataset.storyFilter.toLowerCase()]!==f.value));const status=storyGallery.querySelector('[data-story-count]');if(status)status.textContent=cards.filter(c=>!c.hidden).length+' verified projects';};filters.forEach(f=>f.addEventListener('change',render));render();}

const transformationTabs=[...document.querySelectorAll('[data-transformation]')];
function chooseTransformation(tab){transformationTabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected;});}
transformationTabs.forEach((tab,i)=>{tab.addEventListener('click',()=>chooseTransformation(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(i+1)%transformationTabs.length;if(event.key==='ArrowLeft')next=(i+transformationTabs.length-1)%transformationTabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=transformationTabs.length-1;if(next!==undefined){event.preventDefault();chooseTransformation(transformationTabs[next]);transformationTabs[next].focus();}});});

const roomAnnotations=[...document.querySelectorAll('[data-room-annotation]')];
roomAnnotations.forEach(annotation=>{const trigger=annotation.querySelector('.storage-room-marker'),tip=annotation.querySelector('.storage-room-tip');const show=()=>{roomAnnotations.forEach(other=>{if(other!==annotation){other.querySelector('.storage-room-marker').setAttribute('aria-expanded','false');other.querySelector('.storage-room-tip').hidden=true;other.classList.remove('is-open');}});trigger.setAttribute('aria-expanded','true');tip.hidden=false;annotation.classList.add('is-open');};const hide=()=>{trigger.setAttribute('aria-expanded','false');tip.hidden=true;annotation.classList.remove('is-open');};annotation.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')show();});annotation.addEventListener('pointerleave',()=>{if(!annotation.contains(document.activeElement))hide();});annotation.addEventListener('focusin',show);annotation.addEventListener('focusout',()=>setTimeout(()=>{if(!annotation.contains(document.activeElement))hide();},0));trigger.addEventListener('click',show);annotation.querySelector('.storage-tip-close').addEventListener('click',hide);annotation.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();hide();}});document.addEventListener('pointerdown',e=>{if(!annotation.contains(e.target))hide();});});
